local cache={}
local order={}
local LIMIT=96
local function get(k)
  local c=cache[k]
  if c then return c end
  local z=I[k]
  if not z then return nil end
  local p=z-(z%128)
  p=p/128
  local n=z%128
  c={}
  for i=1,n do c[i]={D[p],D[p+1]} p=p+2 end
  cache[k]=c
  order[#order+1]=k
  if #order>LIMIT then cache[table.remove(order,1)]=nil end
  return c
end
